mapper.select:
select item_id, is_deleted, cover_image, wall_images, game_name, price, details, create_time, update_time
from game_trading
where is_deleted = 0

    and item_id < #{cursor}

order by item_id desc
limit #{size}

mapper.update:
update game_trading
cover_image = #{coverImage}, wall_images = #{wallImages}, game_name = #{gameName}, price = #{price}, details = #{details}, update_time = #{updateTime}
where item_id = #{itemId} and is_deleted = 0

